from h import *
R(9758847,"باستا بالبيستو والخضار",
"باستا طازجة ولذيذة بالبيستو والخضار، مشبعة وغنية جدًا بالنكهة.",
"4 حصص","حصة واحدة",
["1 حبة كوسا مقطعة أرباعًا وشرائح سميكة","1 باينت (نحو 2 كوب) طماطم كرزية (عنب)","1 حبة فلفل أحمر مقطع مكعبات كبيرة","1 حبة فلفل أصفر مقطع مكعبات كبيرة","½ رطل ريغاتوني أو أي نوع تفضله","2 كوب أوراق ريحان طازجة مكبوسة","3 فصوص ثوم مقشرة","2 ملعقة كبيرة عصير ليمون (نحو نصف ليمونة كبيرة)","¼ كوب من ماء سلق المعكرونة المحفوظ","ملح + فلفل حسب الرغبة","جبن بارميزان نباتي","ريحان طازج","رقائق الفلفل الأحمر"],
["سخّن الفرن مسبقًا إلى 425℉ (218℃) على وضع الشوي بالهواء الساخن، وبطّن صينية خبز كبيرة بورق زبدة.","رتّب الخضار المقطعة في الصينية وحمّصها لمدة 15 دقيقة، أو حتى تصبح الحواف بنية ذهبية.","في أثناء ذلك، اغلِ قدرًا كبيرًا من الماء المملح جيدًا، واسلق المعكرونة وفق تعليمات العبوة حتى تصبح «آل دنتي». صفّها (لكن احتفظ بـ ¼-½ كوب من الماء)، وأعدها إلى القدر، وضعها جانبًا.","في أثناء ذلك، حضّر البيستو. ضع الريحان والثوم وعصير الليمون في محضّر الطعام وشغّله حتى تتفتت المكونات ناعمًا. ثم، والجهاز يعمل، أضف ببطء ¼ كوب (أو أكثر عند الحاجة) من الماء النشوي المحفوظ حتى تصل إلى القوام المطلوب. تذوّق وعدّل الملح والفلفل حسب الحاجة.","أضف البيستو والخضار المحمّصة إلى قدر المعكرونة المصفاة، وامزج جيدًا، ثم قدّم."],
["أضف ملحًا إلى ماء الطهي. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لتمليح الماء بالشكل المثالي في كل مرة.","اطهُ المعكرونة حتى قوام «آل دنتي». لا تفرط في الطهي! تعني «آل دنتي» أن المعكرونة تبقى متماسكة بعد الطهي، مما يعطي قوامًا مثاليًا في كل لقمة. وللتأكد من عدم الإفراط في الطهي، ابدأ بتذوقها قبل بضع دقائق من الموعد المذكور على العبوة. يجب أن تكون طرية لكنها ما تزال متماسكة.","تُحفظ المتبقيات في الثلاجة لمدة 3-4 أيام."],
{"For the pasta":"للباستا","For the pesto":"للبيستو","For garnish/serving":"للتزيين/التقديم"})
R(9759865,"سلوبي جو بالعدس في القدر الكهربائي (إنستانت بوت) (مع تعليمات الطهي على الموقد)",
"سلوبي جو بالعدس في القدر الكهربائي (إنستانت بوت)، طبق مغذٍّ وشهي مليء بالنكهة ومشبع!",
"8 حصص","حصة واحدة",
["1 حبة بصل أصفر مقطعة مكعبات","1 حبة فلفل رومي أحمر مقطعة مكعبات","4 كوب مرق خضار قليل الصوديوم *انظر الملاحظات","1 كوب عدس بني أو أخضر","1 كوب عدس أحمر مجروش","2 ملعقة كبيرة معجون طماطم","2 ملعقة كبيرة صلصة تاماري أو صلصة الصويا إذا كنت لا تتجنب الغلوتين","1 ملعقة صغيرة كمون","1 ملعقة صغيرة بابريكا مدخنة","1 كوب صلصة طماطم أو هريس طماطم *انظر الملاحظات","خبز برغر نباتي أو أي نوع خبز تفضله","سلطة كول سلو","مخلل و/أو بصل مخلل"],
["اختر وضع التحمير (Sauté) في القدر الكهربائي، وأضف البصل والفلفل مع ملعقة أو ملعقتين كبيرتين من الماء وحمّرهما لمدة 2-3 دقائق حتى يلينا. ثم أضف باقي المكونات، وأغلق الغطاء، وحوّل صمام البخار إلى وضع الإغلاق. اضبط الجهاز على الضغط العالي لمدة 6 دقائق. (سيستغرق بناء الضغط من 10 إلى 15 دقيقة قبل بدء العد التنازلي.) عند انتهاء المؤقت، افتح صمام البخار للتفريغ السريع.","قدّم مع الخبز والإضافات، أو تناوله كحساء.","في قدر كبير على نار متوسطة، أضف البصل والفلفل مع ملعقة أو ملعقتين كبيرتين من الماء وحمّرهما لمدة 2-3 دقائق حتى يلينا.","أضف باقي المكونات إلى القدر وانتظر حتى تصل إلى الغليان على نار عالية. بعد الغليان، خفّض النار إلى متوسطة منخفضة واتركها تغلي بهدوء لمدة 25-30 دقيقة، أو حتى ينضج العدس وتُمتص معظم السوائل.","قدّم مع الخبز والإضافات، أو تناوله كحساء."],
["*حوّله إلى حساء: لتحضير حساء سلوبي جو نباتي، أضف كوبًا إضافيًا من صلصة الطماطم وكوبين إضافيين من مرق الخضار إلى القدر. أي استخدم 6 كوب من المرق و2 كوب من الصلصة. لا تضف الملح. إغفال الملح في الوصفة لم يكن سهوًا. إذا كنت تستخدم المرق وصلصة التاماري أو الصويا، فمن المرجح ألا تحتاج إلى ملح إضافي. بعد الطهي، تذوّق وأضف مزيدًا من الملح عند الحاجة. استخدم العدس الأحمر المجروش، وليس العدس الأحمر الكامل. يمتص العدس المجروش كمية أكبر من المرق والصلصة فيصبح الطبق سميكًا بحيث تتماسك الساندويتش جيدًا. إذا لم يتوفر لديك عدس أحمر مجروش، فإن البازلاء الصفراء أو الخضراء المجروشة تؤدي الغرض جيدًا أيضًا. وإذا لم يتوفر لديك أي عدس أو بازلاء مجروشة، فاستخدم كمية أكبر من العدس الأخضر أو البني للحصول على نتائج مشابهة. اضبط التوابل: لا تتردد في زيادة التوابل لرفع النكهة. أنا أبقيها خفيفة التتبيل لتناسب الأطفال، ولكن إذا أردتها حارة فأضف القليل من الفلفل الحار (الكايين) أو رشة أو رشتين من الصلصة الحارة. لنسخة خالية من الصويا: احذف التاماري واستخدم أمينو جوز الهند، أو احذفه وأضف قليلًا من الملح حسب الرغبة. لمزيد من العناصر الغذائية: أضف المزيد من الخضار المقطعة مثل الكرفس والبطاطس المقطعة مكعبات والفطر والبازلاء و/أو الجزر. تُحفظ المتبقيات في الثلاجة لمدة 3-4 أيام أو في الفريزر في وعاء محكم الإغلاق مناسب للتجميد لمدة تصل إلى 3 أشهر."],
{"Optional":"اختياري","Instant Pot Directions":"طريقة الطهي في القدر الكهربائي (إنستانت بوت)","Stove Top Directions":"طريقة الطهي على الموقد"})
R(9761419,"حمص بالهالبينو",
"من طرقي المفضلة لتحضير الحمص، بنكهة حارة قليلًا.",
"6 أشخاص","حصة واحدة",
["1 علبة حمص (15 أونصة)","¼ كوب طحينة","1-2 حبة هالبينو (حسب درجة الحرارة التي تريدها)","1 حبة ليمون أخضر (معصورة)","¼ كوب ماء (أو أكثر قليلًا إذا أردته أخف قوامًا)"],
["صفِّ الحمص واغسله، وانزع سيقان الهالبينو.","ثم ضع كل المكونات في محضّر الطعام أو الخلاط وامزجها حتى تصبح ناعمة كما تريد. يمكنك إضافة المزيد من الماء إذا أردته أخف قوامًا، أو استخدام زيت الزيتون، لكنني أفضّل إبقاءه قليل الدهون فنستخدم الماء.","يمكنك تزيين الحمص بمزيد من الهالبينو المفروم، أو تخطي هذه الخطوة.","قدّمه مع الخضار النيئة أو الخبز أو أي شيء تحبه."],
[],)
R(9762136,"سلطة الشمندر والبروكلي المشوية",
"سلطة شمندر وبروكلي مشوية مليئة بالنكهة لدرجة أنه سيُطلب منك تحضيرها مرارًا وتكرارًا.",
"4 حصص","حصة واحدة",
["3 كوب زهيرات بروكلي مقطعة قطعًا بحجم لقمة","3 كوب شمندر مقطع مكعبات بحجم لقمة","1½ كوب حمص مطبوخ أو معلب (علبة سعة 15 أونصة تقريبًا)","3 ملاعق كبيرة توت بري مجفف (كرانبري)","3 ملاعق كبيرة طحينة","2 ملعقة كبيرة خل التفاح","2 ملعقة كبيرة شراب القيقب","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق الزنجبيل","ملح + فلفل حسب الرغبة"],
["سخّن الفرن مسبقًا إلى 425℉ (218℃) وبطّن صينية خبز كبيرة بورق زبدة.","قطّع البروكلي إلى زهيرات صغيرة، وقشّر الشمندر وقطّعه إلى مكعبات صغيرة بحجم نصف بوصة. رتّب الخضار المقطعة والحمص في طبقة واحدة على صينية الخبز ورشّ عليها الملح والفلفل الأسود. اخبزها لمدة 25-30 دقيقة، حتى يصبح الشمندر طريًا عند غرزه بالشوكة. أخرج الصينية من الفرن واترك الخضار تبرد قليلًا.","في أثناء ذلك، ضع مكونات الصلصة في وعاء صغير وحرّكها بالخفق حتى تمتزج جيدًا.","ضع الشمندر والبروكلي المشويين والحمص والتوت البري المجفف والصلصة في وعاء متوسط/كبير وحرّك حتى تتغطى المكونات بالتساوي. تمتع بسلطة الشمندر والبروكلي وهي طازجة للحصول على أفضل قوام."],
["قطّع الشمندر قطعًا صغيرة لينضج أسرع. أو إذا واجهت صعوبة في تقطيعه إلى قطع صغيرة بما يكفي، فاخبزه 15 دقيقة أولًا، ثم أضف البروكلي والحمص إلى الصينية.","تذوّق صلصة السلطة وعدّلها حسب ذوقك قبل الخلط."],
{"For the Salad":"للسلطة","For the Dressing":"للصلصة"})
